@@ -0,0 +1,70 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, auth } from "./helpers.js";
+
+test("missing or unknown key is 401 in the error shape", async () => {
+  const { handle } = app();
+  const missing = await handle({ path: "/items" });
+  assert.equal(missing.status, 401);
+  assert.equal(missing.body.error.code, "unauthorized");
+  assert.ok(missing.body.error.message);
+
+  const bad = await handle({ path: "/items", headers: auth("no-such-key") });
+  assert.equal(bad.status, 401);
+  assert.equal(bad.body.error.code, "unauthorized");
+});
+
+test("viewer can read but cannot mutate or read audit", async () => {
+  const { handle } = app();
+  const h = auth("viewer-key");
+  assert.equal((await handle({ path: "/items", headers: h })).status, 200);
+
+  const cook = await handle({ method: "POST", path: "/recipes/1/cook", headers: h, body: { portions: 1 } });
+  assert.equal(cook.status, 403);
+  assert.equal(cook.body.error.code, "forbidden");
+
+  const audit = await handle({ path: "/audit", headers: h });
+  assert.equal(audit.status, 403);
+  assert.equal(audit.body.error.code, "forbidden");
+});
+
+test("cook can cook, waste, log temperatures and enter stock-take counts, but not manage", async () => {
+  const { handle } = app();
+  const cookH = auth("cook-key");
+  const mgrH = auth("manager-key");
+
+  assert.equal((await handle({ path: "/items", headers: cookH })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: cookH, body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: cookH, body: { qty: 0.5, reason: "spoiled" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", headers: cookH, body: { location: "fridge", celsius: 3 } })).status, 201);
+
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: mgrH, body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: cookH, body: { batchId: 6, counted: 12 } })).status, 200);
+
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: cookH, body: { location: "fridge" } })).status, 403);
+  assert.equal((await handle({ path: "/audit", headers: cookH })).status, 403);
+});
+
+test("data-changing requests write audit entries listed newest first for managers", async () => {
+  const { handle } = app();
+  const cookH = auth("cook-key");
+  const mgrH = auth("manager-key");
+
+  await handle({ path: "/items", headers: cookH });
+  assert.equal((await handle({ path: "/audit", headers: mgrH })).body.length, 0);
+
+  await handle({ method: "POST", path: "/temperatures", headers: cookH, body: { location: "fridge", celsius: 3 } });
+  await handle({ method: "POST", path: "/stocktakes", headers: mgrH, body: { location: "dry" } });
+
+  const res = await handle({ path: "/audit", headers: mgrH });
+  assert.equal(res.status, 200);
+  assert.equal(res.body.length, 2);
+  assert.deepEqual(
+    res.body.map(({ keyName, method, path, status }) => ({ keyName, method, path, status })),
+    [
+      { keyName: "manager", method: "POST", path: "/stocktakes", status: 201 },
+      { keyName: "cook", method: "POST", path: "/temperatures", status: 201 },
+    ],
+  );
+  assert.ok(res.body[0].time);
+});
